"""Keep the free browser edition's characters and branding in sync with the app."""
import json
from pathlib import Path
import shutil
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from characters import CHARACTERS, DEFAULT_CHARACTER


def main():
    source = ROOT / "browser" / "src"
    source.mkdir(parents=True, exist_ok=True)
    catalog = {slug: dict(metadata, voiceId=metadata["voice"]) for slug, metadata in CHARACTERS.items()}
    (source / "characters.js").write_text(
        "// Generated by scripts/sync_browser_assets.py from characters.py.\n"
        "export const CHARACTERS = " + json.dumps(catalog, ensure_ascii=False, indent=2) + ";\n"
        "export const DEFAULT_CHARACTER = " + json.dumps(DEFAULT_CHARACTER) + ";\n",
        encoding="utf-8",
    )
    paths = ["voice-studio-logo.svg", "voice-studio-logo.png", "voice-studio-favicon.ico"]
    paths += [f"avatars/{metadata['avatar']}" for metadata in CHARACTERS.values()]
    for name in paths:
        original = ROOT / "assets" / name
        if original.is_symlink() or not original.resolve().is_relative_to((ROOT / "assets").resolve()):
            raise RuntimeError("A browser asset must be an ordinary project asset.")
        target = ROOT / "browser" / "public" / "assets" / name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(original, target)
    print(f"Synced {len(catalog)} characters and {len(paths)} branding assets.")


if __name__ == "__main__":
    main()
